function healthSeverityLabel(v){return ({critical:'Критично',important:'Важно',info:'Информация'})[v]||'Важно'}
function healthStatusLabel(v){return ({confirmed:'Подтверждено врачом',suspected:'Подозрение',observation:'Наблюдение'})[v]||'Наблюдение'}
function animalStatusLabel(v){return ({normal:'Обычное состояние',attention:'Требует внимания',critical:'Критично'})[v]||'Обычное состояние'}
function animalStatusIcon(v){return ({normal:'<span class="ui-emoji" aria-hidden="true">●</span>',attention:'<span class="ui-emoji" aria-hidden="true">●</span>',critical:'<span class="ui-emoji" aria-hidden="true">●</span>'})[v]||'<span class="ui-emoji" aria-hidden="true">●</span>'}
function animalStatusClass(v){return ({normal:'status-normal',attention:'status-attention',critical:'status-critical'})[v]||'status-normal'}
