 c.innerHTML=`<div class="dashboard-hero"><div class="animal-hero-icon">${photoMarkup(a,'animal-hero-photo')}</div><div><span class="muted">${esc(b.label)}</span><h2>${esc(a.name)}</h2><p class="muted">${esc(a.species||'')} ${a.breed?'· '+esc(a.breed):''}</p><div class="animal-status-pill ${animalStatusClass(a.status)}">${animalStatusIcon(a.status)} ${esc(animalStatusLabel(a.status))}</div></div></div>${att.length?`<div class="attention dashboard-attention"><b>⚠ Требует внимания</b><div class="chips">${att.map(x=>`<span>${esc(x.title)}</span>`).join('')}</div></div>`:''}${quickActions()}<div class="grid dashboard-stats"><div class="card stat-card"><span class="muted">Доступные животные</span><strong>${state.animals.length}</strong></div><div class="card stat-card"><span class="muted">Навыки освоены</span><strong>${mastered}/${state.skills.length||0}</strong></div><div class="card stat-card"><span class="muted">Особенности</span><strong>${dev.length}</strong></div></div><div class="card today-tip"><b>Умные значения</b><span>Последние использованные значения подставляются автоматически. Животное, автор, дата и время — уже выбраны.</span></div><div class="grid dashboard-two"><div class="card"><div class="top"><h3>Особенности развития и поведения</h3><button type="button" class="secondary" id="homeDev">Открыть</button></div>${dev.length?`<div class="chips">${dev.slice(0,8).map(x=>`<span>${esc(x.category)}: ${esc(x.title)} · ${esc(developmentFeatureLabel(x.status))}</span>`).join('')}</div>`:'<p class="muted">Особенности не зафиксированы.</p>'}</div><div class="card"><h3>Навыки</h3>${state.skills.length?`<div class="skill-summary">${state.skills.map(s=>`<div class="summary-row"><span>${esc(s.name)}</span><span class="badge ${s.mastered?'ok':'pending'}">${s.mastered?'Освоен':'В работе'}</span></div>`).join('')}</div>`:'<p class="muted">Навыки ещё не добавлены.</p>'}</div></div><div id="todayList"><div class="card muted">Загружаю события…</div></div>`;
 document.querySelector('#homeDev')?.addEventListener('click',()=>developmentFeatures(c)); document.querySelectorAll('[data-quick]').forEach(x=>x.onclick=()=>quick(x.dataset.quick));
 c.querySelectorAll('#guidanceSlot').forEach(x=>x.remove());
