/** Поиск ккал/100г в state.foodCatalog (точное, затем частичное совпадение). */
function getCustomKcalPer100(name){
 if(!name)return null;
 const n=String(name).toLowerCase().trim().replace(/\s+/g,' ');
 const cat=state.foodCatalog||[];
 // exact match first (prefer animal-specific if present — already ordered)
 let hit=cat.find(x=>(x.name_normalized||x.name||'').toLowerCase().trim()===n);
 if(hit)return Number(hit.kcal_per_100g);
 hit=cat.find(x=>{const k=(x.name_normalized||x.name||'').toLowerCase();return k&&(n.includes(k)||k.includes(n));});
 return hit?Number(hit.kcal_per_100g):null;
}
/** Подгружает food_product_catalog (animal + global) в state.foodCatalog. */
async function loadFoodCatalog(animalId){
 try{
  const q=animalId?`?animal_id=${encodeURIComponent(animalId)}`:'';
  const d=await api('food-products'+q);
  state.foodCatalog=d.products||[];
 }catch{state.foodCatalog=state.foodCatalog||[];}
}
/** Оценка ккал порции: custom catalog → KCAL_PER_100G → keyword heuristics. */
function estimateProductKcal(name,grams){
 if(!name||!grams||!(Number(grams)>0))return null;
 const n=String(name).toLowerCase().trim().replace(/\s+/g,' ');
 // 1) user catalog from DB
 let per100=getCustomKcalPer100(name);
 // 2) built-in table
 if(per100==null)per100=KCAL_PER_100G[n];
 if(per100==null){
  for(const [k,v] of Object.entries(KCAL_PER_100G)){
   if(n.includes(k)||k.includes(n)){per100=v;break;}
  }
 }
 if(per100==null){
  // keyword heuristics
  if(/корм|сух/.test(n))per100=350;
  else if(/консерв|влажн|паштет|пауч/.test(n))per100=90;
  else if(/куриц|индейк|индюш/.test(n))per100=130;
  else if(/говяд|телят/.test(n))per100=180;
  else if(/рыб|лос|треск|хек|тун|форел|минтай/.test(n))per100=110;
  else if(/рис|греч|овсян|каш|пшен|перлов|киноа|булгур/.test(n))per100=110;
  else if(/яблок|груш|банан|персик|абрикос|слив|апельсин|мандар|киви|манго|дыня|арбуз|виноград|вишня|клубник|малин|черник|ягод|фрукт|хурма|гранат/.test(n))per100=50;
  else if(/морков|тыкв|кабач|цукин|броккол|капуст|огурец|помидор|томат|свекл|свёкл|перец|баклажан|шпинат|салат|сельдерей|петруш|укроп|овощ|зелен|редис|батат/.test(n))per100=30;
  else if(/мяс|фарш/.test(n))per100=180;
  else if(/творог|кефир|йогурт|молок/.test(n))per100=70;
  else return null;
 }
 return Math.round(per100*Number(grams)/100);
}

/**
 * Модалка приёма пищи: строки продуктов, ＋ продукт,  сохранить ккал/100г в food_product_catalog.
 * Авто-ккал через estimateProductKcal (каталог БД → встроенная таблица → эвристики).
 */
async function openMealForm(dietId, day, meal){
  const isEdit=!!meal;
  const existing=document.querySelector('#mealFormModal');
  if(existing) existing.remove();
  await loadFoodCatalog(state.animal?.id);
  const products=isEdit?arr(meal.products).map(p=>({name:p.name||'',grams:p.grams??'',calories:p.calories??''})):[{name:'',grams:'',calories:''}];
  const wrap=document.createElement('div');
  wrap.id='mealFormModal';
  wrap.className='modal-backdrop';
  wrap.innerHTML=`<div class="modal-card" role="dialog" style="max-width:520px;width:95%">
    <div class="top"><div><h3>${isEdit?'Изменить приём пищи':'Новый приём пищи'}</h3>
    <p class="muted">Добавьте продукты кнопкой ниже. Граммы и ккал необязательны.</p></div>
    <button type="button" class="secondary" id="mealFormClose">×</button></div>
    <form id="mealForm">
      <div class="formgrid">
        <label>Время<input name="time" type="time" required value="${esc(isEdit?String(meal.time_of_day||'').slice(0,5):'08:00')}"></label>
        <label>Название<input name="title" required value="${esc(isEdit?(meal.title||''):'Утренний рацион')}" placeholder="Утренний рацион"></label>
      </div>
      <div style="margin:14px 0 8px;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
        <div><b>Продукты</b><br><small class="muted">Ккал подставляются по справочнику.  — сохранить свой продукт (ккал/100г) в базу</small></div>
        <button type="button" class="secondary" id="addProductRow">＋ Добавить продукт</button>
      </div>
      <div id="productRows"></div>
      <div class="actions" style="margin-top:16px">
        <button type="submit">${isEdit?'Сохранить':'Добавить приём'}</button>
        <button type="button" class="secondary" id="mealFormCancel">Отмена</button>
      </div>
    </form>
  </div>`;
  document.body.appendChild(wrap);
  document.body.classList.add('modal-open');

  const rowsEl=wrap.querySelector('#productRows');
  function renderRows(){
    rowsEl.innerHTML=products.map((p,i)=>`<div class="product-row" data-idx="${i}" style="display:grid;grid-template-columns:1.3fr 0.6fr 0.6fr auto auto;gap:8px;margin-bottom:8px;align-items:end">
      <label>Название<input data-f="name" value="${esc(p.name)}" placeholder="Корм / мясо / овощи"></label>
      <label>Граммы<input data-f="grams" type="number" min="0" step="1" value="${p.grams!==''&&p.grams!=null?esc(String(p.grams)):''}" placeholder="г"></label>
      <label>Ккал<input data-f="calories" type="number" min="0" step="1" value="${p.calories!==''&&p.calories!=null?esc(String(p.calories)):''}" placeholder="ккал"></label>
      <button type="button" class="secondary save-product-kcal" data-idx="${i}" title="Сохранить ккал/100г в справочник" style="margin-bottom:2px;font-size:12px;padding:8px 10px"></button>
      <button type="button" class="danger remove-product" data-idx="${i}" title="Удалить" style="margin-bottom:2px">×</button>
    </div>`).join('')||'<p class="muted">Нажмите «＋ Добавить продукт»</p>';
    rowsEl.querySelectorAll('input').forEach(inp=>{
      inp.addEventListener('input',()=>{
        const row=inp.closest('[data-idx]');
        const idx=Number(row.dataset.idx);
        products[idx][inp.dataset.f]=inp.value;
        // Auto-estimate kcal when name or grams change (don't overwrite manual kcal if user typed it after estimate)
        if(inp.dataset.f==='name'||inp.dataset.f==='grams'){
          const est=estimateProductKcal(products[idx].name,products[idx].grams);
          if(est!=null){
            products[idx].calories=est;
            const kcalInput=row.querySelector('input[data-f="calories"]');
            if(kcalInput && (kcalInput.dataset.manual!=='1' || inp.dataset.f==='grams' || inp.dataset.f==='name')){
              // refresh estimate when name/grams change unless user locked manual
              if(kcalInput.dataset.manual!=='1'){
                kcalInput.value=est;
                products[idx].calories=est;
              }
            }
          }
        }
        if(inp.dataset.f==='calories'){
          inp.dataset.manual='1'; // user edited kcal manually — don't overwrite
        }
      });
      if(inp.dataset.f==='name'||inp.dataset.f==='grams'){
        inp.addEventListener('blur',()=>{
          const row=inp.closest('[data-idx]');
          const idx=Number(row.dataset.idx);
          const kcalInput=row.querySelector('input[data-f="calories"]');
          if(kcalInput && kcalInput.dataset.manual==='1')return;
          const est=estimateProductKcal(products[idx].name,products[idx].grams);
          if(est!=null){
            products[idx].calories=est;
            kcalInput.value=est;
          }
        });
      }
    });
    rowsEl.querySelectorAll('.remove-product').forEach(btn=>{
      btn.onclick=()=>{products.splice(Number(btn.dataset.idx),1);renderRows();};
    });
    rowsEl.querySelectorAll('.save-product-kcal').forEach(btn=>{
      btn.onclick=async()=>{
        const idx=Number(btn.dataset.idx);
        const p=products[idx];
        const name=(p.name||'').trim();
        if(!name){alert('Сначала укажите название продукта');return;}
        const grams=Number(p.grams);
        const totalKcal=Number(p.calories);
        let per100;
        if(grams>0 && totalKcal>=0 && !isNaN(totalKcal)){
          per100=Math.round((totalKcal/grams)*1000)/10; // 1 decimal
        }else if(totalKcal>=0 && !isNaN(totalKcal) && (!grams||!(grams>0))){
          // interpret calories field as already per 100g if no grams
          per100=totalKcal;
        }else{
          alert('Укажите граммы и ккал (или только ккал как значение на 100 г)');return;
        }
        if(per100<0||per100>1000){alert('Получилось '+per100+' ккал/100г — проверьте числа');return;}
        try{
          await api('food-products',{method:'POST',body:JSON.stringify({name,kcal_per_100g:per100,animal_id:state.animal?.id||null})});
          await loadFoodCatalog(state.animal?.id);
          btn.textContent='✓';
          btn.disabled=true;
          setTimeout(()=>{btn.textContent='';btn.disabled=false;},1500);
        }catch(e){alert(e.message||String(e));}
      };
    });
  }
  renderRows();

  wrap.querySelector('#addProductRow').onclick=()=>{products.push({name:'',grams:'',calories:''});renderRows();const last=rowsEl.querySelector('.product-row:last-child input[data-f="name"]');if(last)last.focus();};
  const close=()=>{wrap.remove();document.body.classList.remove('modal-open');};
  wrap.querySelector('#mealFormClose').onclick=close;
  wrap.querySelector('#mealFormCancel').onclick=close;
  wrap.addEventListener('click',e=>{if(e.target===wrap)close();});

  wrap.querySelector('#mealForm').onsubmit=async e=>{
    e.preventDefault();
    const fd=new FormData(e.target);
    const time=fd.get('time');
    const title=fd.get('title')||'Приём пищи';
    const clean=products.filter(p=>(p.name||'').trim()).map(p=>{
      const grams=p.grams!==''&&p.grams!=null?Number(String(p.grams).replace(',','.'))||null:null;
      const calories=p.calories!==''&&p.calories!=null?Number(String(p.calories).replace(',','.'))||null:null;
      return {name:String(p.name).trim(),grams,quantity:grams!=null?grams+' г':'',calories};
    });
    if(!clean.length){alert('Добавьте хотя бы один продукт');return;}
    try{
      if(isEdit){
        await api(`diets/${dietId}/meals`,{method:'PUT',body:JSON.stringify({id:meal.id,day_offset:meal.day_offset,time_of_day:time,title,products:clean,sort_order:meal.sort_order})});
      }else{
        await api(`diets/${dietId}/meals`,{method:'POST',body:JSON.stringify({day_offset:day,time_of_day:time,title,products:clean})});
      }
      close();
      openDietEditor(dietId);
    }catch(err){alert(err.message||String(err));}
  };
}

async function addMeal(dietId, day){
  openMealForm(dietId, day, null);
}

async function editMeal(dietId, meal){
  if(!meal)return;
  openMealForm(dietId, meal.day_offset, meal);
}

async function copyDay(dietId, days){
  const from=prompt('Из какого дня копировать?',String(days[0]??0)); if(from==null)return;
  const toStr=prompt('В какие дни? (через запятую, напр. 1,2,3 или 1-6)','1,2,3,4,5,6'); if(!toStr)return;
  let targets=[];
  toStr.split(',').forEach(part=>{
   part=part.trim();
   if(part.includes('-')){const [a,b]=part.split('-').map(Number); for(let i=a;i<=b;i++)targets.push(i);}
   else targets.push(Number(part));
  });
  targets=targets.filter(n=>!isNaN(n));
  if(!targets.length){alert('Не указаны дни');return;}
  await api(`diets/${dietId}/copy-day`,{method:'POST',body:JSON.stringify({from_day_offset:Number(from),to_day_offsets:targets})});
  openDietEditor(dietId);
 }

